import osimport jsonimport uuidimport loggingfrom datetime import datetimefrom pathlib import Pathfrom flask import Flask, render_template, request, jsonify, send_from_directoryfrom flask_cors import CORS# ================================================================# 1. CONFIGURATION# ================================================================HOST = '0.0.0.0'PORT = int(os.environ.get('PORT', 10000))BASE_DIR = Path(os.environ.get('BASE_DIR', '.'))# Storage pathsPROJECTS_FOLDER = BASE_DIR / 'uploads' / 'projects'PROJECTS_FOLDER.mkdir(parents=True, exist_ok=True)# Logginglogging.basicConfig(    level=logging.INFO,    format='%(asctime)s | %(levelname)s | %(message)s')logger = logging.getLogger('XENA')# ================================================================# 2. FLASK APP# ================================================================app = Flask(__name__,             template_folder='templates',            static_folder='static')app.config['MAX_CONTENT_LENGTH'] = 8 * 1024 * 1024  # 8MB max uploadapp.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', 'xena-pro-secret-2026')CORS(app)# ================================================================# 3. SECURITY - Filename sanitizer# ================================================================def safe_filename(name):    """Sanitize filename to prevent path traversal attacks"""    if not name:        return 'untitled'    # Only allow alphanumeric, dash, underscore    return ''.join(c for c in str(name) if c.isalnum() or c in '-_')# ================================================================# 4. ROUTES# ================================================================@app.route(' /')def index():    """Serve the main application"""    try:        return render_template ('3d.html')    except Exception as e:        logger.error(f'Template error: {e}')        return """        <h1>XENA Pro</h1>        <p>3D Gesture Workspace</p>        <p>If you see this, the frontend is loading...</p>        <p>Check that 3d.html exists in the templates folder.</p>        """, 200@app.route('/health')def health():    """Health check endpoint"""    projects = list(PROJECTS_FOLDER.glob('*.json'))    return jsonify({        'status': 'healthy',        'version': '3.0.0',        'optimized': True,        'on_device_tracking': True,        'projects': len(projects),        'timestamp': datetime.utcnow().isoformat(),        'server': 'XENA Pro (Slim)',    })# ================================================================# 5. PROJECT CRUD OPERATIONS# ================================================================@app.route('/api/projects', methods=['GET'])def list_projects():    """List all saved projects"""    try:        projects = []        for file in PROJECTS_FOLDER.glob('*.json'):            try:                data = json.loads(file.read_text())                projects.append({                    'id': file.stem,                    'name': data.get('project', {}).get('name', 'Untitled'),                    'objects': len(data.get('objects', [])),                    'date': data.get('_metadata', {}).get('saved_at', ''),                })            except Exception as e:                logger.warning(f'Could not read project {file}: {e}')                continue        # Sort by date (newest first)        projects.sort(key=lambda p: p['date'], reverse=True)        return jsonify(projects)    except Exception as e:        logger.error(f'Error listing projects: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/projects', methods=['POST'])def save_project():    """Save a project"""    try:        data = request.get_json(silent=True)        if not data:            return jsonify({'error': 'No data provided'}), 400        # Generate or use provided ID        project_id = safe_filename(data.get('id', str(uuid.uuid4())))        project_name = data.get('project', {}).get('name', 'Untitled')        # Add metadata        data['_metadata'] = {            'saved_at': datetime.utcnow().isoformat(),            'version': '3.0.0',            'id': project_id,            'optimized': True,        }        # Save to file        filepath = PROJECTS_FOLDER / f'{project_id}.json'        filepath.write_text(json.dumps(data, indent=2))        logger.info(f'💾 Project saved: {project_name} ({project_id})')        return jsonify({            'success': True,            'id': project_id,            'name': project_name,            'message': 'Project saved successfully',        })    except Exception as e:        logger.error(f'Error saving project: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/projects/<project_id>', methods=['GET'])def load_project(project_id):    """Load a specific project"""    try:        safe_id = safe_filename(project_id)        filepath = PROJECTS_FOLDER / f'{safe_id}.json'        if not filepath.exists():            return jsonify({'error': 'Project not found'}), 404        data = json.loads(filepath.read_text())        logger.info(f'📂 Project loaded: {safe_id}')        return jsonify(data)    except json.JSONDecodeError:        return jsonify({'error': 'Invalid project file'}), 500    except Exception as e:        logger.error(f'Error loading project: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/projects/<project_id>', methods=['DELETE'])def delete_project(project_id):    """Delete a project"""    try:        safe_id = safe_filename(project_id)        filepath = PROJECTS_FOLDER / f'{safe_id}.json'        if not filepath.exists():            return jsonify({'error': 'Project not found'}), 404        filepath.unlink()        logger.info(f'🗑️ Project deleted: {safe_id}')        return jsonify({            'success': True,            'message': 'Project deleted successfully',        })    except Exception as e:        logger.error(f'Error deleting project: {e}')        return jsonify({'error': str(e)}), 500# ================================================================# 6. STATIC FILE SERVING (for production)# ================================================================@app.route('/static/<path:path>')def serve_static(path):    """Serve static files"""    return send_from_directory('static', path)# ================================================================# 7. MAIN ENTRY POINT# ================================================================if __name__ == '__main__':    logger.info('═' * 60)    logger.info('🚀 XENA Pro Server (Optimized)')    logger.info(f'🌐 http://{HOST}:{PORT}')    logger.info(f'📁 Projects: {PROJECTS_FOLDER}')    logger.info('═' * 60)    logger.info('✅ No MediaPipe on server - tracking is on-device')    logger.info('✅ Lightweight - only handles project storage')    logger.info('═' * 60)    app.run(        host=HOST,        port=PORT,        debug=False,  # Never use debug in production        threaded=True,    )